#  TRADE SCORING LAYER  (deterministic, auditable, reusable by the pipeline)
#
#  IMPORTANT: the weights below are SENSIBLE STARTING POINTS, not validated.
#  They have NOT been back-tested against the SA validation dataset. Treat the
#  letter grades as a structured summary of the existing signals, not as a
#  proven edge. Tune the weights, then validate against real outcomes before
#  relying on them.
# ══════════════════════════════════════════════════════════════════════════════

def _clamp(x, lo=0.0, hi=100.0):
    try:
        return max(lo, min(hi, float(x)))
    except (TypeError, ValueError):
        return lo


def grade_letter(score):
    if score is None:
        return "N/A"
    if score >= 80: return "A"
    if score >= 68: return "B"
    if score >= 55: return "C"
    if score >= 40: return "D"
    return "F"


def compute_fundamental_score(pe, pb, ps, ev_ebit, gross_margin, fcf_yield, roic, rev_growth):
    """0-100 blend of valuation cheapness (60%) and quality (40%).
    Returns None if there is essentially no fundamental data."""
    val_pts, val_w = 0.0, 0.0
    # cheapness: map each multiple to 0-100 (cheaper = higher) against the
    # screener's own thresholds (cheap / expensive boundaries from knowledge_1).
    def cheap(v, cheap_th, exp_th):
        if v is None or v <= 0:
            return None
        if v <= cheap_th:  return 100.0
        if v >= exp_th:    return 0.0
        return (exp_th - v) / (exp_th - cheap_th) * 100.0
    for v, c, e, w in [(pe, 15, 35, 1.0), (pb, 2, 10, 0.7),
                       (ps, 2, 10, 0.7), (ev_ebit, 12, 30, 1.0)]:
        s = cheap(v, c, e)
        if s is not None:
            val_pts += s * w; val_w += w
    val_score = (val_pts / val_w) if val_w > 0 else None

    qual_pts, qual_w = 0.0, 0.0
    if gross_margin is not None:
        qual_pts += _clamp(gross_margin / 60.0 * 100) * 1.0; qual_w += 1.0   # 60%+ = full
    if fcf_yield is not None:
        qual_pts += _clamp(fcf_yield / 5.0 * 100) * 1.0; qual_w += 1.0       # 5%+ = full
    if roic is not None:
        qual_pts += _clamp(roic / 20.0 * 100) * 0.8; qual_w += 0.8          # 20%+ = full
    if rev_growth is not None:
        qual_pts += _clamp((rev_growth + 10) / 40.0 * 100) * 0.6; qual_w += 0.6  # -10%..+30%
    qual_score = (qual_pts / qual_w) if qual_w > 0 else None

    if val_score is None and qual_score is None:
        return None
    if val_score is None:  return round(qual_score, 0)
    if qual_score is None: return round(val_score, 0)
    return round(0.60 * val_score + 0.40 * qual_score, 0)


def premium_score(vol_rank, iv_hv):
    """Premium richness 0-100. Blends realized-vol rank (current 30d HV vs the
    stock's own trailing 1-year range) and IV/HV, weighted toward IV/HV since it
    directly measures whether options are rich vs what the stock is realizing.
    IV/HV ~1.0 is treated as fairly priced (50), not penalized."""
    parts, weights = [], []
    if iv_hv is not None:
        # IV/HV: 0.7x -> 0, 1.0x -> 50, 1.3x -> 100.
        parts.append(_clamp((iv_hv - 0.7) / (1.3 - 0.7) * 100)); weights.append(0.6)
    if vol_rank is not None:
        parts.append(_clamp(vol_rank)); weights.append(0.4)
    if not parts:
        return 50.0
    return sum(p * w for p, w in zip(parts, weights)) / sum(weights)


def compute_structure_score(mtf, cmf, obv_roc):
    """0-100 trend-structure score: fraction of the multi-timeframe MA stack
    (4h/1D/1W/1M x 50/200) that price sits ABOVE (70%), blended with money flow
    (30%). This is the down-move analogue of CrashScore: CrashScore only sees
    parabolic UP-moves, so a stock in a waterfall downtrend below its whole MA
    stack can clear the crash gate yet still be a falling knife. structure_score
    catches that. ~0 = below everything (NKE-type knife); ~100 = above everything
    (intact uptrend). Starting weights, NOT yet validated against outcomes."""
    above, total = 0, 0
    for tf in ("4h", "1d", "1wk", "1mo"):
        leg = (mtf or {}).get(tf, {}) or {}
        for k in ("ma50_dist", "ma200_dist"):
            d = leg.get(k)
            if d is None:
                continue
            total += 1
            if d > 0:
                above += 1
    ma_frac = (above / total * 100.0) if total else 50.0
    _obv = _clamp(obv_roc if obv_roc is not None else 0.0, -100.0, 100.0)
    flow = _clamp(50.0 + _obv * 0.3 + (cmf if cmf is not None else 0.0) * 100.0)
    return round(_clamp(0.70 * ma_frac + 0.30 * flow), 0)


def _g(ctx, key, default):
    v = ctx.get(key) if ctx else None
    return default if v is None else v


def compute_trade_grades(ctx, opt):
    """Returns {sell_put, wheel, sell_call}, each {score, grade, reasons}.
    ctx = scan-level scalars; opt = options-level scalars.

    Cross-sector revision: a trend-structure term stops downtrending names from
    over-scoring on put-selling (CrashScore is blind to waterfalls); fundamentals
    can no longer rescue broken structure on the Wheel (value-trap guard); hard
    floors for waterfall structure and unsellable liquidity. Starting weights,
    NOT yet validated against the SA outcome dataset."""
    ctx = ctx or {}
    opt = opt or {}
    trend   = _clamp(_g(ctx, "trend_score", 50))
    crash   = _clamp(_g(ctx, "crash_score", 50))
    resist  = _clamp(_g(ctx, "resistance_strength", 30))
    struct  = _clamp(_g(ctx, "structure_score", 50))
    fund    = _g(ctx, "fundamental_score", None)
    fund_v  = _clamp(fund if fund is not None else 50)
    rsi     = _g(ctx, "rsi", 50)
    rally20 = _g(ctx, "rally_20d", None)

    liq  = _clamp(_g(opt, "liquidity_score", 50))
    prem = premium_score(opt.get("vol_rank"), opt.get("iv_hv"))
    ed   = opt.get("earnings_days")

    # vol_safety (0-100): the VALIDATED Sell-Put risk driver. Notebook 08 raced
    # realized volatility vs structure_score out-of-sample against forward drawdown
    # and realized vol won decisively (OOS rank-IC 0.21 vs 0.09, all 4 splits) —
    # structure was largely a volatility proxy with no residual value. So low
    # realized vol = low drawdown risk = safe to sell puts. Maps 30-day annualized
    # realized vol (hv30, %) to a 0-100 safety score: ~20% vol -> 100, ~70% -> 0.
    # Falls back to structure_score only if hv30 is unavailable (options path
    # didn't compute it), preserving graceful degradation.
    hv = _g(opt, "hv30", None)
    if hv is not None and hv > 0:
        vol_safety = _clamp((70.0 - hv) / (70.0 - 20.0) * 100.0)
        vol_src = "vol %d%% ann" % round(hv)
    else:
        vol_safety = struct
        vol_src = "vol n/a -> structure %d" % struct

    # Shared hard gates for the two put-selling grades (Sell Put, Wheel).
    def apply_put_caps(score, reasons):
        if crash >= 60:
            note = "CrashScore %d gate (no puts)" % crash
            if rally20 is not None:
                note += "; 20d move %+.0f%%" % rally20
            score = min(score, 35.0); reasons.append(note)
        if struct < 25:
            score = min(score, 54.0)
            reasons.append("waterfall: price below MA stack (structure %d)" % struct)
        if liq < 35:
            score = min(score, 54.0)
            reasons.append("thin chain (liquidity %d)" % liq)
        if ed is not None and 0 <= ed <= 45:
            score = min(score, 45.0); reasons.append("earnings in %d d" % ed)
        return score, reasons

    # ── Sell Put ──────────────────────────────────────────────────────────────
    # VALIDATED (notebook 08): realized volatility is the dominant predictor of
    # forward drawdown — it ranks drawdown risk ~2.4x better than structure_score
    # out-of-sample, and structure adds no residual value once vol is present. So
    # vol_safety is now the primary risk driver. premium and liquidity remain as
    # economic / executability inputs (are we paid, can we trade it — not risk
    # signals). structure_score is NO LONGER a weighted term (redundant with vol);
    # it survives only as (a) the structure<25 falling-knife cap and (b) displayed
    # trend context. See knowledge_2 / knowledge_8 for the validation.
    sp_base = (0.55 * vol_safety + 0.25 * prem + 0.20 * liq)
    sp_reasons = ["%s (driver)" % vol_src, "premium %d" % prem,
                  "liquidity %d" % liq, "structure %d" % struct]
    sp, sp_reasons = apply_put_caps(sp_base, sp_reasons)

    # ── Wheel: put + willing to own, so fundamentals matter -- but they cannot
    #    lift broken structure. A cheap falling knife is still a falling knife.
    #    Inherits the volatility-led sp_base above. ──
    wh = 0.70 * sp_base + 0.30 * fund_v
    wh_reasons = ["%s (driver)" % vol_src, "premium %d" % prem, "liquidity %d" % liq,
                  "structure %d" % struct, "fundamentals %d" % fund_v]
    if struct < 30 and fund_v > 60:
        wh = min(wh, sp_base)
        wh_reasons.append("value-trap guard: fundamentals capped by broken structure")
    wh, wh_reasons = apply_put_caps(wh, wh_reasons)

    # ── Sell Call: overhead resistance + rich IV + flat/weak trend ────────────
    trend_inv  = _clamp(100 - trend)
    overbought = _clamp((rsi - 50) * 2)
    sc = (0.35 * resist + 0.25 * prem + 0.20 * trend_inv + 0.10 * liq + 0.10 * overbought)
    sc_reasons = ["resistance %d" % resist, "premium %d" % prem,
                  "trend-fade %d" % trend_inv, "liquidity %d" % liq]

    def pack(score, reasons):
        s = round(_clamp(score), 0)
        return {"score": s, "grade": grade_letter(s), "reasons": reasons}

    return {
        "sell_put":   pack(sp, sp_reasons),
        "wheel":      pack(wh, wh_reasons),
        "sell_call":  pack(sc, sc_reasons),
    }

def compute_liquidity(all_puts, all_calls, spot, total_chain_oi, avg_volume, today_chain_vol=None):
    """LiquidityScore 0-100 from underlying volume, chain OI, bid/ask spread, and
    current chain volume. Single-ticker thresholds (handoff item 1)."""
    contracts = [c for c in (all_puts + all_calls) if c.get("bid", 0) > 0 and c.get("ask", 0) > 0]
    # spread % over the 10 contracts nearest the money
    near = sorted(contracts, key=lambda c: abs(c.get("strike", 0) - spot))[:10] if spot else contracts[:10]
    spreads, widths = [], []
    for c in near:
        b, a = c["bid"], c["ask"]
        mid = (a + b) / 2.0
        if mid > 0:
            spreads.append((a - b) / mid)
            widths.append(a - b)
    import statistics
    med_spread = statistics.median(spreads) if spreads else None
    med_width  = statistics.median(widths) if widths else None
    if today_chain_vol is None:
        today_chain_vol = sum(c.get("volume", 0) or 0 for c in (all_puts + all_calls))

    def norm(v, lo, hi):
        if v is None: return 0.5
        if v <= lo: return 0.0
        if v >= hi: return 1.0
        return (v - lo) / (hi - lo)

    n_vol    = norm(avg_volume, 100_000, 5_000_000)
    n_oi     = norm(total_chain_oi, 1_000, 25_000)       # single-name 27-45 DTE OI is small
    n_spread = 1.0 - norm(med_spread, 0.03, 0.35) if med_spread is not None else 0.5  # tighter=better
    n_today  = norm(today_chain_vol, 500, 50_000)

    score = (0.30 * n_vol + 0.30 * n_oi + 0.25 * n_spread + 0.15 * n_today) * 100
    score = round(_clamp(score), 0)
    return {
        "score": score,
        "grade": grade_letter(score),
        "avg_volume": int(avg_volume) if avg_volume else None,
        "total_chain_oi": int(total_chain_oi) if total_chain_oi else None,
        "median_spread_pct": round(med_spread * 100, 1) if med_spread is not None else None,
        "median_spread_width": round(med_width, 2) if med_width is not None else None,
        "today_chain_volume": int(today_chain_vol) if today_chain_vol else 0,
    }


def fetch_options(ticker, ctx=None):
    """Fetch full options chain for all expirations in 27-45 DTE window."""
    import datetime

    yt = yf.Ticker(ticker)
    try:
        expirations = yt.options
    except Exception as e:
        return {"error": f"Could not fetch expirations: {e}"}
    if not expirations:
        return {"error": "No options expirations available"}

    today = datetime.date.today()

    valid_exps = []
    for exp_str in expirations:
        try:
            exp_date = datetime.date.fromisoformat(exp_str)
            dte = (exp_date - today).days
            if 27 <= dte <= 45:
                valid_exps.append((exp_str, dte))
        except Exception:
            continue

    if not valid_exps:
        return {"error": "No expirations in 27-45 DTE window"}

    try:
        spot = float(yt.info.get("regularMarketPrice") or yt.info.get("currentPrice") or 0)
    except Exception:
        spot = 0

    def clean_contract(row, dte_days, is_put):
        try:
            strike = float(getattr(row, "strike", 0) or 0)
            bid = float(getattr(row, "bid", 0) or 0)
            ask = float(getattr(row, "ask", 0) or 0)
            iv_raw = getattr(row, "impliedVolatility", 0)
            iv = float(iv_raw) if iv_raw and not np.isnan(float(iv_raw)) else 0
            oi_raw = getattr(row, "openInterest", 0)
            oi = int(oi_raw) if oi_raw and not np.isnan(float(oi_raw)) else 0
            vol_raw = getattr(row, "volume", 0)
            vol = int(vol_raw) if vol_raw and not np.isnan(float(vol_raw)) else 0
            sym = str(getattr(row, "contractSymbol", ""))

            if bid < 0.05 or oi < 1 or iv <= 0:
                return None

            delta = bs_delta(spot, strike, dte_days, iv, is_put=is_put)
            if delta is None:
                return None
            delta_abs = abs(delta)

            theta = bs_theta(spot, strike, dte_days, iv, is_put=is_put)
            ann_yield = (bid / strike) * (365 / dte_days) * 100 if strike > 0 and dte_days > 0 else 0
            be = (strike - bid) if is_put else (strike + bid)

            return {
                "contractSymbol": sym,
                "strike": strike,
                "bid": round(bid, 2),
                "ask": round(ask, 2),
                "delta": round(delta_abs, 3),
                "theta": round(theta, 4) if theta is not None else None,
                "impliedVolatility": round(iv, 4),
                "openInterest": oi,
                "volume": vol,
                "annYield": round(ann_yield, 1),
                "breakeven": round(be, 2),
            }
        except Exception:
            return None

    all_puts = []
    all_calls = []
    expirations_meta = []

    for exp_str, dte in valid_exps:
        try:
            chain = yt.option_chain(exp_str)
            exp_date = datetime.date.fromisoformat(exp_str)
            exp_label = exp_date.strftime("%b %-d, %Y")

            exp_puts = []
            exp_calls = []

            for _, row in chain.puts.iterrows():
                c = clean_contract(row, dte, True)
                if c:
                    c["expiration"] = exp_label
                    c["dte"] = dte
                    exp_puts.append(c)

            for _, row in chain.calls.iterrows():
                c = clean_contract(row, dte, False)
                if c:
                    c["expiration"] = exp_label
                    c["dte"] = dte
                    exp_calls.append(c)

            if exp_puts:
                best = min(exp_puts, key=lambda x: abs(x["delta"] - 0.20))
                best["optimal"] = True
            if exp_calls:
                best = min(exp_calls, key=lambda x: abs(x["delta"] - 0.20))
                best["optimal"] = True

            all_puts.extend(exp_puts)
            all_calls.extend(exp_calls)
            _put_oi_exp  = sum(c["openInterest"] for c in exp_puts)
            _call_oi_exp = sum(c["openInterest"] for c in exp_calls)
            _tot_oi_exp  = _put_oi_exp + _call_oi_exp
            _pc_oi_exp   = round(_put_oi_exp / _call_oi_exp, 3) if _call_oi_exp > 0 else None
            expirations_meta.append({
                "exp": exp_label, "dte": dte,
                "puts": len(exp_puts), "calls": len(exp_calls),
                "put_oi": _put_oi_exp, "call_oi": _call_oi_exp,
                "total_oi": _tot_oi_exp, "pc_oi_ratio": _pc_oi_exp,
            })

        except Exception:
            continue

    # ── Implied move: ATM straddle nearest expiration ─────────────────────────
    implied_move = None
    try:
        if all_puts and all_calls and spot > 0:
            first_exp = valid_exps[0][0]
            first_exp_label = datetime.date.fromisoformat(first_exp).strftime("%b %-d, %Y")
            first_dte = valid_exps[0][1]
            fp = [c for c in all_puts if c['expiration'] == first_exp_label]
            fc = [c for c in all_calls if c['expiration'] == first_exp_label]
            if fp and fc:
                atm_put  = min(fp, key=lambda x: abs(x['strike'] - spot))
                atm_call = min(fc, key=lambda x: abs(x['strike'] - spot))
                straddle_mid = ((atm_put['bid'] + atm_put['ask']) / 2 +
                                (atm_call['bid'] + atm_call['ask']) / 2)
                exp_move = straddle_mid * 0.85
                exp_move_pct = (exp_move / spot) * 100
                implied_move = {
                    "move_dollars": round(exp_move, 2),
                    "move_pct": round(exp_move_pct, 2),
                    "upper": round(spot + exp_move, 2),
                    "lower": round(spot - exp_move, 2),
                    "straddle_mid": round(straddle_mid, 2),
                    "expiration": first_exp_label,
                    "dte": first_dte,
                }
    except Exception:
        implied_move = None

    # ── IV skew: 20-delta put IV vs 20-delta call IV ──────────────────────────
    skew = None
    try:
        if all_puts and all_calls:
            first_exp_label = valid_exps[0][1] and datetime.date.fromisoformat(valid_exps[0][0]).strftime("%b %-d, %Y")
            fp = [c for c in all_puts  if c['expiration'] == first_exp_label and c.get('delta')]
            fc = [c for c in all_calls if c['expiration'] == first_exp_label and c.get('delta')]
            if fp and fc:
                put20  = min(fp, key=lambda x: abs(x['delta'] - 0.20))
                call20 = min(fc, key=lambda x: abs(x['delta'] - 0.20))
                put_iv  = put20['impliedVolatility']
                call_iv = call20['impliedVolatility']
                if call_iv > 0:
                    skew_ratio = put_iv / call_iv
                else:
                    skew_ratio = None
                skew = {
                    "put_iv": round(put_iv * 100, 1),
                    "call_iv": round(call_iv * 100, 1),
                    "put_strike": put20['strike'],
                    "call_strike": call20['strike'],
                    "ratio": round(skew_ratio, 3) if skew_ratio else None,
                    "label": (
                        "normal (put fear > call greed)" if skew_ratio and skew_ratio > 1.1 else
                        "flat (put/call IV equal)" if skew_ratio and 0.9 <= skew_ratio <= 1.1 else
                        "reverse (call IV > put IV)" if skew_ratio else "unknown"
                    ),
                    "expiration": first_exp_label,
                }
    except Exception:
        skew = None

    # ── CHANGE 2 & 3: IV rank + unusual OI ───────────────────────────────────
    iv_rank = None
    unusual_oi = None
    try:
        # IV rank: use ATM IV from the nearest expiration as IV_now,
        # then compute range from all IV values across the full chain.
        # This is a cross-sectional proxy (not time-series), clearly labeled as such.
        all_ivs = [c['impliedVolatility'] for c in all_puts + all_calls
                   if c.get('impliedVolatility') and c['impliedVolatility'] > 0]
        if len(all_ivs) >= 5:
            iv_now = None
            # Use ATM call IV as the spot IV reference
            if all_calls:
                first_exp_label_iv = datetime.date.fromisoformat(valid_exps[0][0]).strftime("%b %-d, %Y")
                fc_iv = [c for c in all_calls if c['expiration'] == first_exp_label_iv]
                if fc_iv:
                    atm_c = min(fc_iv, key=lambda x: abs(x['strike'] - spot))
                    iv_now = atm_c['impliedVolatility']
            if iv_now is None:
                iv_now = float(np.median(all_ivs))
            iv_low  = float(np.percentile(all_ivs, 10))
            iv_high = float(np.percentile(all_ivs, 90))
            if iv_high > iv_low:
                rank = (iv_now - iv_low) / (iv_high - iv_low) * 100
                iv_rank = round(min(max(rank, 0), 100), 1)
            else:
                iv_rank = None
    except Exception:
        iv_rank = None

    try:
        # Unusual OI: aggregate OI by strike across all expirations
        # Build a per-strike OI map (put OI, call OI, total OI)
        strike_oi = {}
        for c in all_puts:
            s = c['strike']
            if s not in strike_oi:
                strike_oi[s] = {'put_oi': 0, 'call_oi': 0}
            strike_oi[s]['put_oi'] += c['openInterest']
        for c in all_calls:
            s = c['strike']
            if s not in strike_oi:
                strike_oi[s] = {'put_oi': 0, 'call_oi': 0}
            strike_oi[s]['call_oi'] += c['openInterest']

        total_put_oi  = sum(v['put_oi']  for v in strike_oi.values())
        total_call_oi = sum(v['call_oi'] for v in strike_oi.values())
        total_chain_oi = total_put_oi + total_call_oi

        pc_oi_ratio = round(total_put_oi / total_call_oi, 3) if total_call_oi > 0 else None

        # Top 3 strikes by total OI
        ranked = sorted(
            [{"strike": s,
              "put_oi": v['put_oi'],
              "call_oi": v['call_oi'],
              "total_oi": v['put_oi'] + v['call_oi'],
              "pct_of_chain": round((v['put_oi'] + v['call_oi']) / total_chain_oi * 100, 1)
                              if total_chain_oi > 0 else 0}
             for s, v in strike_oi.items()],
            key=lambda x: -x['total_oi']
        )[:3]

        # Flag unusual concentration: top strike > 15% of chain OI
        concentration_flag = (
            len(ranked) > 0 and
            total_chain_oi > 0 and
            ranked[0]['pct_of_chain'] > 15.0
        )

        unusual_oi = {
            "total_put_oi": total_put_oi,
            "total_call_oi": total_call_oi,
            "total_chain_oi": total_chain_oi,
            "pc_oi_ratio": pc_oi_ratio,
            "top_strikes": ranked,
            "concentration_flag": concentration_flag,
        }
    except Exception:
        unusual_oi = None
    # ─────────────────────────────────────────────────────────────────────────

    # ── IV/HV ratio, liquidity score, and trade grades ───────────────────────
    hv30 = avg_volume = atm_iv = iv_hv = vol_rank = None
    try:
        _h = yf.download(ticker, period="2y", interval="1d", auto_adjust=True, progress=False)
        if isinstance(_h.columns, pd.MultiIndex):
            _h.columns = _h.columns.get_level_values(0)
        _h = _h.dropna(subset=["Close"])
        if len(_h) > 31:
            _lr = np.log(_h["Close"] / _h["Close"].shift(1))
            # rolling 30-day annualized realized vol (%), full history
            _hv = (_lr.rolling(30).std() * np.sqrt(252) * 100).dropna()
            if len(_hv) > 0:
                hv30 = round(float(_hv.iloc[-1]), 1)
                # Vol rank: where current 30d HV sits in the stock's own trailing
                # ~1-year range. Smile-free surrogate for "is vol rich right now?"
                _win = _hv.tail(252)
                if len(_win) >= 30:
                    vol_rank = round(float((_win <= _hv.iloc[-1]).sum()) / len(_win) * 100, 0)
            avg_volume = float(_h["Volume"].tail(20).mean())
    except Exception:
        pass
    try:
        _atm = min((c for c in (all_puts + all_calls) if c.get("impliedVolatility", 0) > 0),
                   key=lambda c: abs(c["strike"] - spot)) if spot else None
        atm_iv = round(_atm["impliedVolatility"] * 100, 1) if _atm else None
    except Exception:
        atm_iv = None
    if atm_iv and hv30 and hv30 > 0:
        iv_hv = round(atm_iv / hv30, 2)

    _total_oi = unusual_oi["total_chain_oi"] if unusual_oi else 0
    try:
        liquidity = compute_liquidity(all_puts, all_calls, spot, _total_oi, avg_volume)
    except Exception:
        liquidity = None

    grades = None
    if ctx is not None:
        try:
            _opt = {
                "vol_rank": vol_rank,
                "iv_rank": iv_rank,
                "iv_hv": iv_hv,
                "hv30": hv30,
                "liquidity_score": liquidity["score"] if liquidity else None,
                "earnings_days": ctx.get("earnings_days"),
                "pc_oi_ratio": unusual_oi["pc_oi_ratio"] if unusual_oi else None,
            }
            grades = compute_trade_grades(ctx, _opt)
        except Exception:
            grades = None

    # ── Full-chain OI across ALL listed expirations (not just 27-45 DTE) ──────
    # The window loop above only sees 27-45 DTE. Sean/Franklin want the true
    # whole-chain total plus OI labelled per available expiration. fetch_options
    # is a lazy per-ticker call, so the extra option_chain fetches here only cost
    # a few seconds when a single name's chain is opened.
    full_chain_oi = None
    all_exp_oi = []
    try:
        _fp = _fc = 0
        for _es in expirations:
            try:
                _ed = datetime.date.fromisoformat(_es)
            except Exception:
                continue
            _dte = (_ed - today).days
            if _dte < 0:
                continue
            try:
                _ch = yt.option_chain(_es)
                _p = int(_ch.puts["openInterest"].fillna(0).sum())
                _c = int(_ch.calls["openInterest"].fillna(0).sum())
            except Exception:
                continue
            _fp += _p
            _fc += _c
            all_exp_oi.append({
                "exp": _ed.strftime("%b %-d, %Y"),
                "dte": _dte,
                "put_oi": _p,
                "call_oi": _c,
                "total_oi": _p + _c,
                "pc_oi_ratio": round(_p / _c, 3) if _c > 0 else None,
                "in_window": 27 <= _dte <= 45,
            })
        all_exp_oi.sort(key=lambda x: x["dte"])
        _ft = _fp + _fc
        if _ft > 0:
            full_chain_oi = {
                "total_put_oi": _fp,
                "total_call_oi": _fc,
                "total_chain_oi": _ft,
                "pc_oi_ratio": round(_fp / _fc, 3) if _fc > 0 else None,
                "n_expirations": len(all_exp_oi),
            }
    except Exception:
        full_chain_oi = None
        all_exp_oi = []

    return {
        "spot": spot,
        "expirations": expirations_meta,
        "puts": all_puts,
        "calls": all_calls,
        "implied_move": implied_move,
        "skew": skew,
        "iv_rank": iv_rank,
        "unusual_oi": unusual_oi,
        "full_chain_oi": full_chain_oi,
        "all_exp_oi": all_exp_oi,
        "hv30": hv30,
        "atm_iv": atm_iv,
        "iv_hv": iv_hv,
        "vol_rank": vol_rank,
        "avg_volume": int(avg_volume) if avg_volume else None,
        "liquidity": liquidity,
        "grades": grades,
    }


# ── Main ticker scan ──────────────────────────────────────────────────────────

def compute_avwap(df, anchor_date):
    try:
        idx = df.index
        if hasattr(idx, 'tz') and idx.tz is not None:
            if hasattr(anchor_date, 'tz_localize'):
                anchor_date = anchor_date.tz_localize(idx.tz) if anchor_date.tzinfo is None else anchor_date.tz_convert(idx.tz)
        else:
            if hasattr(anchor_date, 'tz_localize') and anchor_date.tzinfo is not None:
                anchor_date = anchor_date.tz_localize(None)
    except Exception:
        pass
    subset = df[df.index >= anchor_date].copy()
    if len(subset) < 2:
        return None
    tp = (subset['High'] + subset['Low'] + subset['Close']) / 3
    vtp = tp * subset['Volume']
    cum_vtp = vtp.cumsum()
    cum_vol = subset['Volume'].cumsum()
    avwap = cum_vtp / cum_vol.replace(0, np.nan)
    variance = ((tp - avwap) ** 2 * subset['Volume']).cumsum() / cum_vol.replace(0, np.nan)
    std = variance.apply(lambda x: x**0.5 if x >= 0 else 0)
    val = float(avwap.iloc[-1])
    s = float(std.iloc[-1])
    return {
        'avwap': round(val, 2),
        's1_up': round(val + s, 2),
        's1_dn': round(val - s, 2),
        's2_up': round(val + 2*s, 2),
        's2_dn': round(val - 2*s, 2),
        'std': round(s, 2),
    }


def find_confluence_levels(price, avwap_dict, mtf, high_52w, low_52w):
    candidates = []

    for anchor_name, av in avwap_dict.items():
        if av is None:
            continue
        label_map = {
            '52w_high': '52wH AVWAP',
            'ytd':      'YTD AVWAP',
            'ytd_low':  'YTD Low AVWAP',
        }
        base = label_map.get(anchor_name, anchor_name + ' AVWAP')
        candidates.append((av['avwap'],  base))
        candidates.append((av['s1_up'],  base + ' +1σ'))
        candidates.append((av['s1_dn'],  base + ' -1σ'))
        candidates.append((av['s2_up'],  base + ' +2σ'))
        candidates.append((av['s2_dn'],  base + ' -2σ'))

    tf_labels = {'4h': '4h', '1d': '1D', '1wk': '1W', '1mo': '1M'}
    for tf_key, tf_label in tf_labels.items():
        tf = mtf.get(tf_key, {})
        if tf.get('ma50'):
            candidates.append((tf['ma50'],  f'{tf_label} 50 MA'))
        if tf.get('ma200'):
            candidates.append((tf['ma200'], f'{tf_label} 200 MA'))

    if high_52w:
        candidates.append((high_52w, '52w High'))
    if low_52w:
        candidates.append((low_52w, '52w Low'))

    increment = 25 if price > 100 else 10
    lo = int(price * 0.5 / increment) * increment
    hi = int(price * 1.6 / increment) * increment + increment
    for rn in range(lo, hi + increment, increment):
        if rn > 0:
            candidates.append((float(rn), f'${rn} round'))

    candidates = [(p, l) for p, l in candidates if p and p > 0]
    candidates.sort(key=lambda x: x[0])

    clusters = []
    used = [False] * len(candidates)
    threshold = 0.02

    for i, (p, l) in enumerate(candidates):
        if used[i]:
            continue
        cluster_prices = [p]
        cluster_labels = [l]
        for j in range(i+1, len(candidates)):
            if used[j]:
                continue
            if abs(candidates[j][0] - p) / p <= threshold:
                cluster_prices.append(candidates[j][0])
                cluster_labels.append(candidates[j][1])
                used[j] = True
        used[i] = True

        if len(cluster_labels) >= 2:
            mid = sum(cluster_prices) / len(cluster_prices)
            dist_pct = (mid - price) / price * 100
            role = 'resistance' if mid > price else 'support'
            strength = len(cluster_labels)
            clusters.append({
                'price': round(mid, 2),
                'price_lo': round(min(cluster_prices), 2),
                'price_hi': round(max(cluster_prices), 2),
                'sources': cluster_labels,
                'strength': strength,
                'dist_pct': round(dist_pct, 1),
                'role': role,
            })

    clusters.sort(key=lambda x: (-x['strength'], abs(x['dist_pct'])))
    return clusters[:8]


def scan_ticker(ticker):
    raw = yf.download(ticker, start="2020-01-01", auto_adjust=True, progress=False)
    if isinstance(raw.columns, pd.MultiIndex):
        raw.columns = raw.columns.get_level_values(0)
    if len(raw) < 250:
        return {"error": f"Insufficient data for {ticker}"}

    df = compute_indicators(raw.copy())
    df = df.dropna(subset=["ma200", "rsi", "vol_rank"])
    if len(df) == 0:
        return {"error": f"No valid data for {ticker}"}

    pr = pd.DataFrame(index=df.index)
    pr["rvol_10d"] = pct_rank(df["rvol_10d"])
    pr["vol_rank"] = 1 - pct_rank(df["vol_rank"])
    pr["ma_distance"] = pct_rank(df["ma_distance"])
    pr["vol_compression"] = pct_rank(df["vol_compression"])
    pr["rally_5d"] = pct_rank(df["rally_5d"])
    pr["rally_20d"] = pct_rank(df["rally_20d"])

    trend = ((0.35*pr["rvol_10d"] + 0.25*pr["vol_rank"] + 0.20*pr["ma_distance"] + 0.20*pr["vol_compression"]) * 100).round(1)
    crash = ((0.50*pr["rally_5d"] + 0.30*pr["rally_20d"] + 0.20*pr["vol_compression"]) * 100).round(1)

    t = float(trend.iloc[-1])
    c = float(crash.iloc[-1])
    last = df.iloc[-1]

    if t >= 70 and c >= 70:
        regime = "Blow-off top risk"
    elif t >= 70 and c < 40:
        regime = "Strong trend"
    elif c >= 60:
        regime = "Elevated crash risk"
    elif t >= 60:
        regime = "Trending"
    elif t < 30 and c < 30:
        regime = "No signal"
    else:
        regime = "Neutral"

    try:
        yt = yf.Ticker(ticker)
        info = yt.info or {}
        inc_q = yt.quarterly_income_stmt
        bal_q = yt.quarterly_balance_sheet
        cf_q = yt.quarterly_cashflow
    except Exception:
        info = {}
        inc_q = bal_q = cf_q = pd.DataFrame()

    sector = info.get("sector", "Unknown")
    industry = info.get("industry", "Unknown")
    mcap = info.get("marketCap")
    revenue = get_ttm(inc_q, "Total Revenue")
    net_inc = get_ttm(inc_q, "Net Income")
    ebit = get_ttm(inc_q, "EBIT") or get_ttm(inc_q, "Operating Income")
    gross_p = get_ttm(inc_q, "Gross Profit")
    equity = get_ttm(bal_q, "Stockholders Equity", True) or get_ttm(bal_q, "Common Stock Equity", True)
    debt = get_ttm(bal_q, "Total Debt", True)
    cash = get_ttm(bal_q, "Cash And Cash Equivalents", True) or get_ttm(bal_q, "Cash Cash Equivalents", True)
    op_cf = get_ttm(cf_q, "Operating Cash Flow") or get_ttm(cf_q, "Cash Flow From Continuing Operating")
    capex = get_ttm(cf_q, "Capital Expenditure")
    tax_prov = get_ttm(inc_q, "Tax Provision")

    ev = (mcap + debt - cash) if mcap and debt is not None and cash is not None else None
    pe = sdiv(mcap, net_inc, True)
    pb = sdiv(mcap, equity, True)
    ps = sdiv(mcap, revenue, True)
    ev_ebit = sdiv(ev, ebit, True)
    gm = sdiv(gross_p, revenue)
    fcf = (op_cf + capex) if op_cf is not None and capex is not None else None
    fcf_yield = sdiv(fcf, mcap)

    peg = info.get("trailingPegRatio") or info.get("pegRatio")
    if peg is not None:
        try:
            peg = round(float(peg), 2)
        except Exception:
            peg = None

    roic = None
    if ebit is not None and equity is not None and debt is not None and cash is not None and ebit > 0:
        if tax_prov is not None and net_inc is not None and (net_inc + tax_prov) != 0:
            tax_rate = max(0.0, min(tax_prov / (net_inc + tax_prov), 0.5))
        else:
            tax_rate = 0.21
        nopat = ebit * (1 - tax_rate)
        invested_capital = debt + equity - cash
        if invested_capital > 0:
            roic = round((nopat / invested_capital) * 100, 1)

    rev_growth = None
    if inc_q is not None and not inc_q.empty:
        rm = [i for i in inc_q.index if "total revenue" in str(i).lower()]
        if rm:
            rv = inc_q.loc[rm[0]].dropna()
            if len(rv) >= 5 and float(rv.iloc[4]) != 0:
                rev_growth = float(rv.iloc[0]) / float(rv.iloc[4]) - 1

    metrics_used = SECTOR_METRICS.get(sector, ["pe", "pb", "ps", "ev_ebit"])
    cmf = float(last["cmf_20"]) if pd.notna(last["cmf_20"]) else 0
    obv_roc = float(last["obv_roc_20"]) if pd.notna(last["obv_roc_20"]) else 0

    def safe(v, decimals=2):
        if v is None or (isinstance(v, float) and math.isnan(v)):
            return None
        return round(float(v), decimals)

    price_now = safe(last["Close"], 2) or 0
    try:
        mtf = fetch_mtf_inline(ticker, price_now)
    except Exception:
        mtf = {}

    avwap_dict = {}
    try:
        _raw = raw.copy()
        if isinstance(_raw.columns, pd.MultiIndex):
            _raw.columns = _raw.columns.get_level_values(0)
        _close = _raw["Close"].squeeze()
        if hasattr(_close.index, 'tz') and _close.index.tz is not None:
            _close.index = _close.index.tz_localize(None)
        if hasattr(_raw.index, 'tz') and _raw.index.tz is not None:
            _raw.index = _raw.index.tz_localize(None)

        _lookback = _close.tail(252)
        high52_date = _lookback.idxmax()
        low52_date  = _lookback.idxmin()
        ytd_date    = pd.Timestamp(f"{pd.Timestamp.now().year}-01-01")

        avwap_dict['52w_high'] = compute_avwap(_raw, high52_date)
        avwap_dict['ytd']      = compute_avwap(_raw, ytd_date)
        avwap_dict['ytd_low']  = compute_avwap(_raw, low52_date)
    except Exception:
        avwap_dict = {}

    confluences = []
    try:
        confluences = find_confluence_levels(
            price_now,
            avwap_dict,
            mtf,
            safe(last["high_52w"], 2),
            safe(last["low_52w"], 2),
        )
    except Exception:
        confluences = []

    # Earnings date
    # ── Scalars feeding the trade-grade layer (passed to the options endpoint) ──
    _cur_px = float(last["Close"])
    def _conf_strength(role):
        best = 0.0
        for _c in confluences:
            if _c.get("role") != role:
                continue
            _d = abs(_c.get("dist_pct", 999))
            if _d > 15.0:
                continue
            _src = min(_c.get("strength", 0), 4) / 4.0
            _prox = max(0.0, 1.0 - _d / 15.0)
            _s = (0.7 * _src + 0.3 * _prox) * 100
            if _s > best:
                best = _s
        return round(best, 1)
    support_strength = _conf_strength("support")
    resistance_strength = _conf_strength("resistance")
    fundamental_score = compute_fundamental_score(
        pe, pb, ps, ev_ebit,
        gm * 100 if gm else None,
        fcf_yield * 100 if fcf_yield else None,
        roic,
        rev_growth * 100 if rev_growth else None,
    )
    structure_score = compute_structure_score(mtf, cmf, obv_roc)

    earnings_date = None
    earnings_days = None
    earnings_within_window = False
    try:
        import datetime as _dt
        _today = _dt.date.today()
        _tk = yf.Ticker(ticker)

        def _coerce(x):
            if x is None:
                return None
            if isinstance(x, _dt.date) and not hasattr(x, "hour"):
                return x
            if hasattr(x, "date"):
                try:
                    return x.date()
                except Exception:
                    return None
            if isinstance(x, str):
                try:
                    return _dt.date.fromisoformat(x[:10])
                except Exception:
                    return None
            return None

        _cands = []
        # Source 1: .calendar — dict in modern yfinance, DataFrame in older
        try:
            _cal = _tk.calendar
        except Exception:
            _cal = None
        if isinstance(_cal, dict):
            _v = _cal.get("Earnings Date") or _cal.get("earnings_date")
            _seq = _v if isinstance(_v, (list, tuple)) else [_v]
            for _x in _seq:
                _d = _coerce(_x)
                if _d:
                    _cands.append(_d)
        elif _cal is not None and hasattr(_cal, "columns"):
            for _c in ["Earnings Date", "earnings_date", "Earnings date"]:
                if _c in _cal.columns:
                    try:
                        for _x in list(_cal[_c].dropna())[:4]:
                            _d = _coerce(_x)
                            if _d:
                                _cands.append(_d)
                    except Exception:
                        pass
                    break
        # Source 2: get_earnings_dates() fallback (indexed by timestamp)
        if not any(_d >= _today for _d in _cands):
            try:
                _edf = _tk.get_earnings_dates(limit=8)
                if _edf is not None and hasattr(_edf, "index"):
                    for _ts in _edf.index:
                        _d = _coerce(_ts)
                        if _d:
                            _cands.append(_d)
            except Exception:
                pass

        _future = sorted(d for d in _cands if d >= _today)
        if _future:
            _ed = _future[0]
            earnings_date = str(_ed)
            earnings_days = (_ed - _today).days
            earnings_within_window = 0 <= earnings_days <= 45
        elif _cands:
            # only past dates known -> report most recent so the field is never blank
            _past = sorted(_cands)[-1]
            earnings_date = str(_past)
            earnings_days = (_past - _today).days   # negative = already reported
            earnings_within_window = False
    except Exception:
        pass

    # ── CHANGE 1 continued: read volume_surge and spike from last row ─────────
    volume_surge_val = safe(last["volume_surge"], 2)
    volume_spike_val = bool(last["volume_spike"]) if pd.notna(last["volume_spike"]) else False
    # ─────────────────────────────────────────────────────────────────────────

    # ── Chart OHLCV: extract from the raw daily DataFrame already in memory ──
    chart_data = {"daily": [], "weekly": []}
    try:
        _cd = raw.copy()
        if isinstance(_cd.columns, pd.MultiIndex):
            _cd.columns = _cd.columns.get_level_values(0)
        if hasattr(_cd.index, "tz") and _cd.index.tz is not None:
            _cd.index = _cd.index.tz_localize(None)
        # Compute MAs on full history
        _cd["_m50"]  = _cd["Close"].rolling(50).mean()
        _cd["_m200"] = _cd["Close"].rolling(200).mean()
        # Daily bars — last 504 trading days (2 years) for 1Y view headroom
        for ts, row in _cd.tail(504).iterrows():
            try:
                chart_data["daily"].append({
                    "t":    int(pd.Timestamp(ts).timestamp()),
                    "o":    round(float(row["Open"]),   2),
                    "h":    round(float(row["High"]),   2),
                    "l":    round(float(row["Low"]),    2),
                    "c":    round(float(row["Close"]),  2),
                    "v":    int(row["Volume"]),
                    "m50":  round(float(row["_m50"]),  2) if not math.isnan(float(row["_m50"]))  else None,
                    "m200": round(float(row["_m200"]), 2) if not math.isnan(float(row["_m200"])) else None,
                })
            except Exception:
                pass
        # Weekly bars — resample daily to weekly for the 1W/1M/3M/6M/1Y views
        _wk = _cd.resample("W").agg({
            "Open": "first", "High": "max", "Low": "min",
            "Close": "last", "Volume": "sum"
        }).dropna()
        _wk["_m50"]  = _wk["Close"].rolling(50).mean()
        _wk["_m200"] = _wk["Close"].rolling(200).mean()
        for ts, row in _wk.tail(260).iterrows():   # 5 years weekly
            try:
                chart_data["weekly"].append({
                    "t":    int(pd.Timestamp(ts).timestamp()),
                    "o":    round(float(row["Open"]),   2),
                    "h":    round(float(row["High"]),   2),
                    "l":    round(float(row["Low"]),    2),
                    "c":    round(float(row["Close"]),  2),
                    "v":    int(row["Volume"]),
                    "m50":  round(float(row["_m50"]),  2) if not math.isnan(float(row["_m50"]))  else None,
                    "m200": round(float(row["_m200"]), 2) if not math.isnan(float(row["_m200"])) else None,
                })
            except Exception:
                pass
        # Attach 4h bars from mtf fetch
        chart_data["h4"] = mtf.pop("_ohlcv_4h", [])
    except Exception:
        chart_data = {"daily": [], "weekly": [], "h4": []}
    # ─────────────────────────────────────────────────────────────────────────

    return {
        "ticker": ticker.upper(),
        "price": safe(last["Close"], 2),
        "mtf": mtf,
        "sector": sector,
        "industry": industry,
        "market_cap": mcap,
        "trend_score": t,
        "crash_score": c,
        "regime": regime,
        "metrics_used": metrics_used,
        "pe": round(pe, 1) if pe else None,
        "pb": round(pb, 1) if pb else None,
        "ps": round(ps, 1) if ps else None,
        "ev_ebit": round(ev_ebit, 1) if ev_ebit else None,
        "peg": peg,
        "roic": roic,
        "gross_margin": round(gm * 100, 1) if gm else None,
        "fcf_yield": round(fcf_yield * 100, 1) if fcf_yield else None,
        "rev_growth": round(rev_growth * 100, 1) if rev_growth else None,
        "ma50": safe(last["ma50"], 2),
        "ma200": safe(last["ma200"], 2),
        "ma50_roc_1d": safe(last["ma50_roc_1d"], 3),
        "ma50_roc_5d": safe(last["ma50_roc_5d"], 3),
        "ma50_roc_21d": safe(last["ma50_roc_21d"], 3),
        "ma200_roc_1d": safe(last["ma200_roc_1d"], 3),
        "ma200_roc_5d": safe(last["ma200_roc_5d"], 3),
        "ma200_roc_21d": safe(last["ma200_roc_21d"], 3),
        "high_52w": safe(last["high_52w"], 2),
        "low_52w": safe(last["low_52w"], 2),
        "rally_1d": safe(last["rally_1d"] * 100, 2),
        "rally_5d": safe(last["rally_5d"] * 100, 2),
        "rally_20d": safe(last["rally_20d"] * 100, 2),
        "rally_21d": safe(last["rally_21d"] * 100, 2),
        "ma_distance": safe(last["ma_distance"] * 100, 1),
        "rsi": safe(last["rsi"], 1),
        "rvol_10d": safe(last["rvol_10d"] * 100, 1),
        "vol_rank": safe(last["vol_rank"] * 100, 0),
        "vol_compression": safe(last["vol_compression"], 2),
        "volume_surge": volume_surge_val,
        "volume_spike": volume_spike_val,
        "drawdown": safe(last["drawdown"] * 100, 1),
        "cmf": round(cmf, 3),
        "obv_roc": round(obv_roc, 1),
        "avwap": avwap_dict,
        "confluences": confluences,
        "earnings_date": earnings_date,
        "earnings_in_window": earnings_within_window,
        "earnings_days": earnings_days,
        "support_strength": support_strength,
        "resistance_strength": resistance_strength,
        "fundamental_score": fundamental_score,
        "structure_score": structure_score,
        "chart_data": chart_data,
    }


